// The three models andes-sim composes from engines. A model says *which*
// engines run and *how* they combine; the concrete engine(s) are resolved
// separately (built-in qemu, or a discovered verilator:<cfg>).
//
//   fast      = QEMU alone (functional), transparent passthrough.
//   accurate  = one Verilator alone, pure from reset, transparent passthrough.
//   hybrid    = QEMU fast-forwards, Verilator measures the ROI (+ a trigger).
#ifndef ANDES_SIM_MODELS_HPP
#define ANDES_SIM_MODELS_HPP

#include <string_view>

namespace andes_sim {

struct Model {
  std::string_view name;
  std::string_view engines;  // engine composition, for `list models`
  std::string_view notes;
};

inline constexpr Model kModels[] = {
    {"fast", "qemu", "functional; transparent passthrough"},
    {"accurate", "verilator:<cfg>",
     "cycle-accurate, pure from reset; transparent passthrough"},
    {"hybrid", "qemu -> verilator",
     "QEMU fast-forwards, Verilator measures the ROI; pick "
     "--trigger csr|pc|icount|simpoint"},
};

inline const Model* find_model(std::string_view name) {
  for (const Model& m : kModels)
    if (m.name == name) return &m;
  return nullptr;
}

}  // namespace andes_sim

#endif  // ANDES_SIM_MODELS_HPP

