// EngineDescriptor: the parsed result of an engine's `--describe` (or its
// sidecar <bin>.json). This struct IS the contract that QEMU, Verilator, and
// future engines (alioth, sid) speak to join the framework -- see
// docs/engine_interface.md. The framework keeps zero per-engine code; every
// capability it needs comes from here.
#ifndef ANDES_SIM_ENGINE_DESCRIPTOR_HPP
#define ANDES_SIM_ENGINE_DESCRIPTOR_HPP

#include <string>
#include <string_view>
#include <vector>

#include "json.hpp"

namespace andes_sim {

// One role's argv template, e.g. role "accurate-leg" -> {"{bin}",
// "--resume-from-qemu", "{state_in}", ...}. {placeholders} are filled by the
// plan executor (F6).
struct EngineInvoke {
  std::string role;
  std::vector<std::string> argv;
};

struct EngineDescriptor {
  std::string id;                       // "qemu", "verilator:ax45mpv_premium"
  std::string type;                     // qemu | verilator | alioth | sid
  std::string kind;                     // functional | cycle-accurate
  long vlen = 0;                        // 0 = not applicable
  long xlen = 0;
  std::vector<std::string> triggers;    // csr | pc | icount | simpoint
  std::vector<std::string> roles;       // standalone | fast-leg | accurate-leg
  std::vector<std::string> state;       // resume | drain (hybrid_state_v1 caps)
  std::vector<EngineInvoke> invoke;     // argv template per role
  std::string result;                   // stderr:<re> | state.mcycle

  // Filled by the registry, not present in the JSON:
  std::string bin_path;                 // resolved path to the binary
  std::string source;                   // built-in | --describe | sidecar

  const std::vector<std::string>* invoke_for(std::string_view role) const {
    for (const EngineInvoke& iv : invoke)
      if (iv.role == role) return &iv.argv;
    return nullptr;
  }
};

// Build a descriptor from parsed JSON. Returns "" on success or an error
// message naming the first problem (id and type are required).
inline std::string descriptor_from_json(const json::Value& v,
                                        EngineDescriptor& out) {
  if (!v.is_object()) return "descriptor is not a JSON object";

  const json::Value* id = v.find("id");
  if (!id || !id->is_string() || id->str.empty()) return "missing string 'id'";
  out.id = id->as_string();

  const json::Value* type = v.find("type");
  if (!type || !type->is_string()) return "missing string 'type'";
  out.type = type->as_string();

  if (const json::Value* x = v.find("kind")) out.kind = x->as_string();
  if (const json::Value* x = v.find("vlen")) out.vlen = x->as_int();
  if (const json::Value* x = v.find("xlen")) out.xlen = x->as_int();
  if (const json::Value* x = v.find("triggers")) out.triggers = x->as_string_array();
  if (const json::Value* x = v.find("roles")) out.roles = x->as_string_array();
  if (const json::Value* x = v.find("state")) out.state = x->as_string_array();
  if (const json::Value* x = v.find("result")) out.result = x->as_string();

  if (const json::Value* inv = v.find("invoke"); inv && inv->is_object()) {
    for (size_t k = 0; k < inv->keys.size(); ++k)
      out.invoke.push_back({inv->keys[k], inv->vals[k].as_string_array()});
  }
  return "";
}

}  // namespace andes_sim

#endif  // ANDES_SIM_ENGINE_DESCRIPTOR_HPP

// Runtime engine discovery -- the hot-plug seam.
//
// discover_engines() returns the built-in qemu descriptor plus every engine
// found by scanning a directory and asking each binary to self-report via
// `--describe` (falling back to a <bin>.json sidecar). No engine is compiled
// into the framework; dropping a freshly built sim_<cfg> into the scan dir
// makes it appear here with no andes-sim rebuild.
//
// Scan dir: $ANDES_SIM_ENGINES_DIR (colon-separated; REPLACES the default and
// accepts any executable) if set, else <repo>/verilator/build (filtered to
// sim_* binaries).
#ifndef ANDES_SIM_ENGINE_REGISTRY_HPP
#define ANDES_SIM_ENGINE_REGISTRY_HPP

#include <string>
#include <vector>

#include "engine_descriptor.hpp"

namespace andes_sim {

struct Discovery {
  std::vector<EngineDescriptor> engines;   // deduped by id; qemu first
  std::vector<std::string> warnings;       // binaries that failed to describe
};

Discovery discover_engines();

}  // namespace andes_sim

#endif  // ANDES_SIM_ENGINE_REGISTRY_HPP

// Subprocess helpers for andes-sim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/accurate.
#ifndef ANDES_SIM_PROCESS_HPP
#define ANDES_SIM_PROCESS_HPP

#include <string>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// and stderr are redirected to /dev/null. If the child runs longer than
// timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms);

// Run argv to completion with the child INHERITING this process's stdout and
// stderr (its output streams straight to the terminal) and stdin from
// /dev/null; chdir to `cwd` first if non-empty. No capture, no timeout. Returns
// the child's exit code, 128+signal if it was signalled, or -1 on spawn
// failure. Used by `build` to delegate to setup.sh / build_*.sh / make.
int run_inherit(const std::vector<std::string>& argv, const std::string& cwd);

// Run argv to completion with the child INHERITING all three std streams
// (stdin, stdout, stderr) -- the transparent-passthrough mechanism behind
// `run --model fast|accurate`: the engine reads/writes the terminal directly,
// so an interactive gdbstub or semihosting console works unchanged. No chdir,
// no capture, no timeout. Returns the child's exit code, 128+signal if it was
// signalled, or -1 on spawn failure / empty argv.
int exec_passthrough(const std::vector<std::string>& argv);

}  // namespace andes_sim

#endif  // ANDES_SIM_PROCESS_HPP

// Shared-mmap allocation for andes-sim -- a C++ port of tools/hsim_shm.py.
//
// One rule: the caller asks for `size` bytes; we honor HSIM_MMAP_DIR (else
// /dev/shm), statvfs-check free space, allocate a sparse file with
// mkstemp+truncate, and print one status line. No fallback chain, no
// filesystem-type probing. (The HSIM_MMAP_DIR name and "[hsim mmap]" status
// line stay verbatim with the Python golden until the F14 rename.)
#ifndef ANDES_SIM_SHM_HPP
#define ANDES_SIM_SHM_HPP

#include <string>

namespace andes_sim {

// Parse "8G" / "512M" / "1024" / "1.5G" into a positive byte count. On success
// returns the count and leaves `err` empty; on failure returns 0 and sets `err`
// to the argparse-style message. Mirrors hsim_shm.parse_size (fractional values
// truncate, like Python int(float(num) * mult)).
long long parse_size(const std::string& spec, std::string& err);

// Resolve the pinned mmap directory (HSIM_MMAP_DIR if set, else /dev/shm) and
// validate it can hold size + 256 MiB. Returns the directory on success; on
// failure returns "" and sets `err`. Mirrors hsim_shm.select_mmap_dir.
std::string select_mmap_dir(long long size, std::string& err);

// Allocate a sparse mmap file of `size` bytes in the pinned dir (mkstemp +
// truncate), print one "[hsim mmap] <size> at <dir> (free: <free>)" line, and
// return its path. On failure returns "" and sets `err`. Caller owns the file's
// lifetime (unlink when done). Mirrors hsim_shm.allocate.
std::string allocate(long long size, std::string& err,
                     const std::string& prefix = "hsim-shm.");

}  // namespace andes_sim

#endif  // ANDES_SIM_SHM_HPP

