// StateDrain halts the hart via the Debug Module and populates a
// hybrid_state_v1 with the architectural register file. Reuses
// ResumeDriver's DM register constants and DmiBus interface.

#pragma once

#include "hybrid/abstract_command.hpp"
#include "hybrid/dmi_poll.hpp"
#include "hybrid/resume_driver.hpp"
#include "hybrid/state_abi.h"
#include "hybrid/v_regfile_xfer.hpp"

#include <algorithm>
#include <cstdint>

namespace hybrid
{

class StateDrain
{
public:
  using RD = ResumeDriver;

  explicit StateDrain(DmiBus& bus)
      : bus_{bus}
  {}

  // F16: stash the warmup-window snapshot (mcycle, minstret captured K
  // retires after vsim entry). Both drain() and drain_with_passthrough()
  // copy these into the returned state. Zero when MeasureStartSnapshot
  // never fired (K=0 or workload exited inside the warmup window).
  void set_warmup_snapshot(uint64_t mcycle, uint64_t minstret)
  {
    warmup_mcycle_   = mcycle;
    warmup_minstret_ = minstret;
  }

  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
  // drain_with_passthrough when the QEMU 1 snapshot is available.
  auto drain() -> hybrid_state_v1
  {
    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
                   "StateDrain halt");

    hybrid_state_v1 state{};
    state.magic   = HYBRID_STATE_MAGIC;
    state.version = HYBRID_STATE_VERSION;
    state.flags   = HYBRID_FLAG_RV64;
    state.priv    = 3;

    for (uint16_t i = 1; i < 32; ++i)
      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");

    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
    state.mcycle_at_measure_start   = warmup_mcycle_;
    state.minstret_at_measure_start = warmup_minstret_;
    return state;
  }

  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 so
  // post-vsim FP modifications are captured (otherwise the stale QEMU 1
  // snapshot leaks through to QEMU 2). When HYBRID_FLAG_V is set, also
  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
  // and vreg remain pass-through (read-only / too large for DM).
  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
  // contribution would otherwise be discarded as the passthrough preserves
  // QEMU1's pre-handoff value.
  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
  {
    auto state       = input;
    const auto fresh = drain();
    std::copy(std::begin(fresh.gpr) + 1, std::end(fresh.gpr),
              std::begin(state.gpr) + 1);
    state.pc = fresh.pc;

    if (input.flags & HYBRID_FLAG_FP) {
      for (uint16_t i = 0; i < 32; ++i)
        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
    }

    if (input.flags & HYBRID_FLAG_V) {
      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
    }

    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));

    // V data regfile: dump v0..v31 to the shared scratch region via the
    // Program Buffer LAST -- after every architectural read above -- so the
    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
    // cannot corrupt the values already captured. The simulator's
    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
    if (input.flags & HYBRID_FLAG_V)
      pb_v_data_sweep(bus_, kVScratchGpa, HYBRID_VLEN_BYTES_MAX, input.vlenb,
                      /*load=*/false);

    state.mcycle_at_measure_start   = warmup_mcycle_;
    state.minstret_at_measure_start = warmup_minstret_;
    return state;
  }

private:
  DmiBus& bus_;
  uint64_t warmup_mcycle_   = 0;  // F16: zero when warmup boundary never fired
  uint64_t warmup_minstret_ = 0;
};

}  // namespace hybrid

// CsrTrigger pre-scans an instruction buffer (typically the loadable
// executable segments of an ELF) for `csrw 0x7C0, *` instructions and
// records their PCs. At retire time the simulator queries lookup(pc) to
// decide whether to drain state and hand back to QEMU.
//
// Pure logic: no SystemC, no DMI bus. Decoupled from GPR access -- the
// caller resolves runtime-kind rs1 values via decode_csrrw_rs1.

#pragma once

#include "hybrid/insn_match.h"

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <optional>
#include <span>
#include <unordered_map>
#include <vector>

namespace hybrid
{

struct CsrTriggerHit
{
  hybrid_handoff_kind kind;
  uint32_t insn;
};

inline auto decode_csrrw_rs1(uint32_t insn) -> uint8_t
{
  return static_cast<uint8_t>((insn >> 15) & 0x1Fu);
}

class CsrTrigger
{
public:
  void scan_buffer(std::span<const uint8_t> code, uint64_t base_pc)
  {
    std::size_t i = 0;
    while (i + sizeof(uint16_t) <= code.size()) {
      uint16_t lo = 0;
      std::memcpy(&lo, code.data() + i, sizeof(lo));

      const bool is_32 = (lo & 0x3u) == 0x3u;
      if (is_32) {
        if (i + sizeof(uint32_t) > code.size()) break;
        uint32_t insn = 0;
        std::memcpy(&insn, code.data() + i, sizeof(insn));
        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
        if (hybrid_match_handoff_insn(insn, &kind)) {
          hits_.insert_or_assign(base_pc + i, CsrTriggerHit{kind, insn});
        }
        i += sizeof(uint32_t);
      } else {
        i += sizeof(uint16_t);
      }
    }
  }

  // PC-trigger mode: insert a synthetic hit without scanning. Used when the
  // orchestrator passes --hybrid-exit-pc on the CLI; in that case the binary
  // need not contain a magic csrwi, and `insn` is unused (HandoffController
  // decodes the insn only on the RUNTIME arm; PC mode only inserts EXIT).
  void add_pc_hit(uint64_t pc, hybrid_handoff_kind kind)
  {
    hits_.insert_or_assign(pc, CsrTriggerHit{kind, /*insn=*/0u});
  }

  auto lookup(uint64_t pc) const -> std::optional<CsrTriggerHit>
  {
    if (auto it = hits_.find(pc); it != hits_.end()) return it->second;
    return std::nullopt;
  }

  auto empty() const -> bool { return hits_.empty(); }

  // Collect every recorded PC whose hit matches `kind`. The result is sorted
  // ascending so callers (e.g. the ROI kanata-gate derivation) get a stable
  // order regardless of hash-map iteration order.
  auto pcs_of_kind(hybrid_handoff_kind kind) const -> std::vector<uint64_t>
  {
    std::vector<uint64_t> pcs;
    pcs.reserve(hits_.size());
    for (const auto& [pc, hit]: hits_)
      if (hit.kind == kind) pcs.push_back(pc);
    std::sort(pcs.begin(), pcs.end());
    return pcs;
  }

private:
  std::unordered_map<uint64_t, CsrTriggerHit> hits_;
};

}  // namespace hybrid

// B7: doctest for the QEMU-plugin V-drain decision function.
//
// The plugin's V-state drain used to gate on `v->vlenb` (the register
// handle truthiness) AND `s.vlenb > 0`. The combination silently omits
// the V block whenever the stub advertises some V state but not vlenb,
// confusing "stub broke" with "V disabled at runtime". This test pins
// the four-case truth table: SKIP when no V at all, ABORT when partial,
// SKIP when V advertised but disabled (vlenb=0), OK otherwise.

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include "doctest.h"

#include "hybrid/v_drain_policy.h"

TEST_CASE("no V advertised at all -> SKIP")
{
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/0, /*has_other_v=*/0,
                              /*vlenb_value=*/0)
        == HYBRID_V_DRAIN_SKIP);
}

TEST_CASE("vlenb missing but vtype/vl/etc advertised -> ABORT")
{
  // The "broken stub" case the original gate hid. Don't silently emit a
  // zero-filled V block: the resume side then writes garbage into QEMU2.
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/0, /*has_other_v=*/1,
                              /*vlenb_value=*/0)
        == HYBRID_V_DRAIN_ABORT);
}

TEST_CASE("vlenb advertised but value=0 -> SKIP (V disabled at runtime)")
{
  // QEMU may expose the V feature in XML even when V is not enabled in
  // the CPU at runtime; vlenb then reads 0. Treat as "no V live".
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/0)
        == HYBRID_V_DRAIN_SKIP);
}

TEST_CASE("vlenb advertised, value>0 -> OK")
{
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/16)
        == HYBRID_V_DRAIN_OK);
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/1,
                              /*vlenb_value=*/64)
        == HYBRID_V_DRAIN_OK);
}

TEST_CASE("vlenb advertised alone (no other V) is still ABORT-equivalent: "
          "policy treats vlenb-only as no V context")
{
  // Edge case: stub advertises vlenb but no other V regs. This is
  // unusual; treat as SKIP since we have no V data to actually drain.
  // (Documented behaviour, not a runtime failure mode QEMU emits.)
  CHECK(hybrid_v_drain_policy(/*has_vlenb=*/1, /*has_other_v=*/0,
                              /*vlenb_value=*/16)
        == HYBRID_V_DRAIN_SKIP);
}

